import { assign, slice } from './util';
import { createVNode, createTagCompat } from './create-element';

/**
 * Clones the given VNode, optionally adding attributes/props and replacing its children.
 * @param {import('./internal').VNode} vnode The virtual DOM element to clone
 * @param {object} props Attributes/props to add when cloning
 * @param {Array<import('./internal').ComponentChildren>} rest Any additional arguments will be used as replacement children.
 * @returns {import('./internal').VNode}
 */
export function cloneElement(vnode, props, children) {
	let normalizedProps = assign({}, vnode.props),
		key,
		ref,
		i;
	for (i in props) {
		if (i == 'key') key = props[i];
		else if (i == 'ref') ref = props[i];
		else normalizedProps[i] = props[i];
	}

	if (arguments.length > 2) {
		normalizedProps.children =
			arguments.length > 3 ? slice.call(arguments, 2) : children;
	}

	return createVNode(
		vnode.type,
		normalizedProps,
		key || vnode.key,
		ref || vnode.ref,
		null
	);
}

export function ClassNameProps(props) {
	this.className = props.className;
	this.classProp = props.class;
}

export function createClassNameProps(type, props) {
	const tagCtx = createTagCompat(type);
	return {
		classNames: new ClassNameProps(props),
		tag: tagCtx.tag,
		aliases: tagCtx.aliases,
		env: tagCtx.env
	};
}

